  const flightsByConfig=new Map(); D.flights.forEach(f=>{if(!flightsByConfig.has(f.configId))flightsByConfig.set(f.configId,[]);flightsByConfig.get(f.configId).push(f);});
  const app={routeResponseId:D.witness.responseId,view:'grid',config:D.witness.configId,flight:D.witness.flightId,point:D.witness.responseId,gridArrival:'all',gridMach:'all',gridEvidence:'all',showUncomputed:true,flightMode:'route',checkpoint:0,exaggeration:30,cloudExaggeration:10,experiment:'all',treatment:'union',fuelMultiplier:'all',compatibleOnly:true,forceMode:'recorded',terminalIndex:6,windEast:20,windNorth:5,windUp:0,labMach:.655,labTemp:245,heading:170,playing:null};
