  $('#scene-download').onclick=()=>{const out=document.createElement('canvas');out.width=canvas.width;out.height=canvas.height+94;const c=out.getContext('2d');c.fillStyle='#192e3b';c.fillRect(0,0,out.width,out.height);c.drawImage(canvas,0,0);c.fillStyle='#e8e3d6';c.font='20px sans-serif';c.fillText('MH370 Flight Dynamics Lab · '+$('#scene-tag').textContent,22,canvas.height+34);c.font='14px sans-serif';c.fillText('Catalogue de50a52 · '+(app.view==='forces'?'Schematic directions · see viewer for units and assumptions':app.view==='flight'?'Saved states · schematic connectors · airborne positions':'Declared grid · symbol denotes evidence, not probability'),22,canvas.height+63);out.toBlob(b=>{const a=document.createElement('a');a.href=URL.createObjectURL(b);a.download='MH370-'+app.view+'-view.png';a.click();setTimeout(()=>URL.revokeObjectURL(a.href),1000);});};
