    wireSelect('grid-arrival',v=>{app.gridArrival=v;renderGrid(false);});wireSelect('grid-mach',v=>{app.gridMach=v;renderGrid(false);});wireSelect('grid-evidence',v=>{app.gridEvidence=v;renderGrid(false);});$('#grid-uncomputed').onchange=e=>{app.showUncomputed=e.target.checked;renderGrid(false);};$('#grid-clear').onclick=()=>{app.gridArrival=app.gridMach=app.gridEvidence='all';app.showUncomputed=true;renderGrid(true);};
    const s=emptyScene(), y0=-4.4; s.polygons.push({vertices:[[-8.2,y0,-6.1],[8.2,y0,-6.1],[8.2,y0,6.1],[-8.2,y0,6.1]],color:'#425a643b',opacity:.5});
