    const selected=configMap.get(app.config);if(selected&&gridMatches(selected)){const p=gridPos(selected);s.points.push({p,id:selected.id,color:colors.white,stroke:colors.amber,strokeWidth:2,size:5,shape:'diamond'});s.lines.push({a:[p[0],y0,p[2]],b:p,color:colors.amber,dash:[3,4],opacity:.85});s.labels.push({p,text:`A${String(selected.arrival).padStart(2,'0')} · M${fmt(selected.mach,3)}`,dy:-20,size:11,color:colors.white});}
